#include <iostream>
#include <numeric>
#include <string>

class Rational {
private:
    int numerator;
    int denominator;

    void reduce() {
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        int g = std::gcd(numerator, denominator);
        if (g != 0) {
            numerator /= g;
            denominator /= g;
        }
    }

public:
    Rational(int n = 0, int d = 1) : numerator(n), denominator(d) {
        reduce();
    }

    // Unary +
    Rational operator+() const {
        return *this;
    }

    // Unary -
    Rational operator-() const {
        return Rational(-numerator, denominator);
    }

    // Prefix ++ : returns lvalue reference
    Rational& operator++() {
        numerator += denominator;
        reduce();
        return *this;
    }

    // Postfix ++ : returns rvalue copy of old state
    Rational operator++(int) {
        Rational temp(*this);
        numerator += denominator;
        reduce();
        return temp;
    }

    std::string toString() const {
        return std::to_string(numerator) + "/" + std::to_string(denominator);
    }
};

int main() {
    Rational r2(2, 3);
    Rational r3 = -r2;
    std::cout << "r2 is " << r2.toString() << "\n";
    std::cout << "r3 is " << r3.toString() << "\n";

    Rational r4(2, 3);
    Rational r5 = ++r4;
    std::cout << "r5 is " << r5.toString() << "\n";
    std::cout << "r4 is " << r4.toString() << "\n";

    Rational r1(2, 3);
    Rational r6 = r1++;
    std::cout << "r1 is " << r1.toString() << "\n";
    std::cout << "r6 is " << r6.toString() << "\n";

    return 0;
}

#include <iostream>

class Date {
private:
    int year;
    int month;
    int day;

public:
    Date(int y, int m, int d) : year(y), month(m), day(d) {}

    // Friend function declaration
    friend void modifyDateYear(Date& date, int newYear);

    // Friend class declaration
    friend class DateViewer;
};

// Free function granted friendship
void modifyDateYear(Date& date, int newYear) {
    date.year = newYear; // Direct access to private field
}

// Class granted friendship
class DateViewer {
public:
    static void display(const Date& date) {
        std::cout << date.year << "-" << date.month << "-" << date.day << "\n";
    }
};

int main() {
    Date birthDate(2010, 3, 4);
    DateViewer::display(birthDate);

    modifyDateYear(birthDate, 2000);
    DateViewer::display(birthDate);

    return 0;
}
